# تولیدشده خودکار از builtin/*.py - ابزارهای داخلی که با شروع سرور کاشته می‌شوند
SEEDS = {
    'add_ui_extension': '# builtin v1\nimport os, re\n\nDESCRIPTION = "Extend the chat app UI with a new tab or panel. run(name, request) where request describes the feature"\n\nPROMPT = """Write a small JavaScript snippet that adds a feature to a mobile chat app.\nOnly this API exists (no imports, no external URLs, no eval):\n  ext.addTab(title, function(container){ ... })   // renders into the container element; called each time the tab opens\n  ext.post(path, obj)  // returns Promise of parsed JSON from the app backend, e.g. ext.post(\'/api/chat\', {{msg:\'hello\'}})\nKeep it short, use plain DOM (container.innerHTML, buttons, inputs). Right-to-left Persian labels are fine.\nFeature requested: {request}\nReply with exactly one ```javascript code block and nothing else."""\n\n\ndef validate(code):\n    if len(code) > 6000:\n        return False, "too long"\n    if "ext.addTab" not in code:\n        return False, "must call ext.addTab"\n    if re.search(r"eval\\(|document\\.cookie|https?://|import\\s|XMLHttpRequest|WebSocket", code):\n        return False, "forbidden construct"\n    for a, b in ("()", "{}", "[]"):\n        if code.count(a) != code.count(b):\n            return False, f"unbalanced {a}{b}"\n    return True, ""\n\n\ndef run(name="", request=""):\n    import agent\n    name = re.sub(r"[^a-z0-9_]", "_", str(name).lower())[:30].strip("_") or "ext"\n    txt = agent.llm(PROMPT.format(request=request))\n    m = re.search(r"```(?:\\w+)?\\n(.*?)```", txt, re.S)\n    code = (m.group(1) if m else txt).strip()\n    ok, why = validate(code)\n    if not ok:\n        return f"افزونه رد شد ({why}). دوباره با توضیح ساده\u200cتر بخواه."\n    d = agent.ROOT / "ui_ext"\n    d.mkdir(exist_ok=True)\n    (d / f"{name}.js").write_text(code, encoding="utf-8")\n    (d / f"{name}.js.off").unlink(missing_ok=True)\n    return f"افزونه «{name}» ذخیره شد. صفحه را ببند و دوباره باز کن تا تب جدید بیاید. اگر خطا بدهد خودکار غیرفعال می\u200cشود."\n\n\ndef selftest():\n    good = "ext.addTab(\'x\', function(c){ c.innerHTML = \'<b>hi</b>\'; });"\n    return validate(good)[0] and not validate("alert(1)")[0] and not validate(good + " eval(\'1\')")[0]\n',
    'make_game': '# builtin v1\nimport json, os, re, time\n\nDESCRIPTION = "Build a playable mobile game with the Phaser engine from a short spec (kind catch or dodge)"\n\nTEMPLATE = r"""<!doctype html><html lang="fa"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">\n<title>__TITLE__</title>\n<style>html,body{margin:0;background:#111;height:100%;overflow:hidden;touch-action:none}</style></head><body>\n<script src="/engines/phaser.min.js"></script>\n<script>\nconst CFG = __CFG__;\nconst W = 360, H = 640, hex = c => parseInt(c.replace(\'#\', \'\'), 16);\nclass Main extends Phaser.Scene {\n  constructor() { super(\'main\'); }\n  create() {\n    this.physics.resume();\n    this.score = 0; this.lives = CFG.lives; this.over = false; this.t0 = null;\n    this.add.rectangle(W / 2, H / 2, W, H, hex(CFG.bg));\n    this.player = this.add.rectangle(W / 2, H - 60, 48, 48, hex(CFG.player_color));\n    this.physics.add.existing(this.player);\n    this.player.body.setCollideWorldBounds(true);\n    this.items = this.physics.add.group();\n    this.enemies = this.physics.add.group();\n    this.hud = this.add.text(10, 10, \'\', { fontSize: \'20px\', color: \'#ffffff\' });\n    this.msg = this.add.text(W / 2, H / 2, \'\', { fontSize: \'26px\', color: \'#ffffff\', align: \'center\' }).setOrigin(0.5);\n    this.keys = this.input.keyboard.createCursorKeys();\n    this.input.on(\'pointermove\', p => { if (!this.over && p.isDown) this.player.x = Phaser.Math.Clamp(p.x, 24, W - 24); });\n    this.input.on(\'pointerdown\', p => {\n      if (this.over) this.scene.restart();\n      else this.player.x = Phaser.Math.Clamp(p.x, 24, W - 24);\n    });\n    if (CFG.kind === \'catch\') {\n      this.time.addEvent({ delay: 700, loop: true, callback: () => this.spawn(this.items, CFG.item_color, true) });\n    }\n    this.time.addEvent({ delay: CFG.kind === \'catch\' ? 1100 : 600, loop: true, callback: () => this.spawn(this.enemies, CFG.enemy_color, false) });\n    this.physics.add.overlap(this.player, this.items, (p, i) => { i.destroy(); this.score++; if (this.score >= CFG.target) this.finish(true); });\n    this.physics.add.overlap(this.player, this.enemies, (p, e) => { e.destroy(); this.lives--; if (this.lives <= 0) this.finish(false); });\n  }\n  spawn(group, col, round) {\n    if (this.over) return;\n    const x = Phaser.Math.Between(20, W - 20);\n    const o = round ? this.add.circle(x, -12, 14, hex(col)) : this.add.rectangle(x, -12, 28, 28, hex(col));\n    this.physics.add.existing(o);\n    group.add(o);\n    o.body.setVelocityY(CFG.speed + Phaser.Math.Between(0, 90));\n  }\n  finish(win) {\n    this.over = true;\n    this.msg.setText((win ? CFG.win_text : CFG.lose_text) + \'\\n\' + CFG.score_label + \': \' + this.score + \'\\n(tap)\');\n    this.physics.pause();\n  }\n  update(time) {\n    if (this.over) return;\n    if (this.t0 === null) this.t0 = time;\n    this.player.body.setVelocityX(this.keys.left.isDown ? -320 : this.keys.right.isDown ? 320 : 0);\n    [this.items, this.enemies].forEach(g => g.getChildren().slice().forEach(o => { if (o.y > H + 30) o.destroy(); }));\n    if (CFG.kind === \'dodge\') {\n      this.score = Math.floor((time - this.t0) / 1000);\n      if (this.score >= CFG.target) this.finish(true);\n    }\n    this.hud.setText(CFG.score_label + \': \' + this.score + \'   \\u2764 \' + this.lives);\n  }\n}\nnew Phaser.Game({\n  type: Phaser.AUTO, width: W, height: H, backgroundColor: CFG.bg,\n  scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },\n  physics: { default: \'arcade\', arcade: { debug: false } },\n  scene: [Main]\n});\n</script></body></html>\n"""\n\n\ndef _color(v, default):\n    return v if isinstance(v, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", v) else default\n\n\ndef _int(v, default, lo, hi):\n    try:\n        return max(lo, min(hi, int(float(v))))\n    except Exception:\n        return default\n\n\ndef _text(v, default):\n    return str(v)[:40] if v not in (None, "") else default\n\n\ndef run(title="My Game", kind="catch", player_color="#44aaff", item_color="#ffcc44", enemy_color="#ff4444",\n        bg="#1b1b2f", speed=200, target=10, lives=3, win_text="You win!", lose_text="Game over", score_label="Score"):\n    cfg = {\n        "kind": kind if kind in ("catch", "dodge") else "catch",\n        "player_color": _color(player_color, "#44aaff"), "item_color": _color(item_color, "#ffcc44"),\n        "enemy_color": _color(enemy_color, "#ff4444"), "bg": _color(bg, "#1b1b2f"),\n        "speed": _int(speed, 200, 80, 600), "target": _int(target, 10, 3, 200), "lives": _int(lives, 3, 1, 9),\n        "win_text": _text(win_text, "You win!"), "lose_text": _text(lose_text, "Game over"),\n        "score_label": _text(score_label, "Score"),\n    }\n    title = _text(title, "Game")\n    slug = re.sub(r"[^A-Za-z0-9_\\-]+", "_", title).strip("_")[:30] or f"game_{int(time.time())}"\n    html = TEMPLATE.replace("__TITLE__", title.replace("<", "")).replace("__CFG__", json.dumps(cfg, ensure_ascii=False).replace("</", "<\\\\/"))\n    os.makedirs("outputs", exist_ok=True)\n    with open(f"outputs/{slug}.html", "w", encoding="utf-8") as f:\n        f.write(html)\n    return f"outputs/{slug}.html"\n\n\ndef selftest():\n    p = run(title="Selftest Game", kind="dodge", target="5", player_color="not-a-color")\n    s = open(p, encoding="utf-8").read()\n    return all(x in s for x in ("Phaser.Game", "/engines/phaser.min.js", \'"kind": "dodge"\', \'"player_color": "#44aaff"\')) and p.endswith(".html")\n',
}
